func facetOn(p SearchParams, name, value string) bool {
	return checked(facetList(&p, name), value)
}

func facetList(p *SearchParams, name string) []string {
	switch name {
	case "project":
		return p.Projects
	case "space":
		return p.Spaces
	case "label":
		return p.Labels
	}
	return p.People
}

func facetHref(p SearchParams, name, value string) string {
	return p.Href(func(x *SearchParams) {
		x.Page = 1
		var list []string
		on := false
		for _, v := range facetList(x, name) {
			if v == value {
				on = true
				continue
			}
			list = append(list, v)
		}
		if !on {
			list = append(list, value)
		}
		switch name {
		case "project":
			x.Projects = list
		case "space":
			x.Spaces = list
		case "label":
			x.Labels = list
		default:
			x.People = list
		}
	})
}

